   [156]={next_id=157, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="就在你即将踏上沙滩时，耳畔突然响起了一阵奇妙的声音。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [157]={next_id=158, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不是凛冽的风声，也不是海浪拍打礁石的轰鸣，而是一段轻柔的旋律，如同冰下涌动的暖流，穿透了阴沉的天幕与呼啸的寒风，清晰地传入你的耳中。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [158]={next_id=159, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……有人在唱歌？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_14_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [159]={next_id=160, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你下意识停下脚步，循着旋律传来的方向望去。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [160]={next_id=161, abreast_id={}, pType =1, cg_type =5, dialog=0, msg="黑屏转场", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_107.jpg", video_url="", music_id="-2", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="arts/storyPrefab/prefab/common/prefab/StoryMask.prefab", runTalkTime =1000, destoryTime =3000, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [161]={next_id=162, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="平直的海岸线上，礁石嶙峋，而在最高的一块礁石上，伫立着一道纤细的身影。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_107.jpg", video_url="", music_id="97", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [162]={next_id=163, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她一身墨绿的衣装，墨色的碎发迎着风扬起，露出光洁的额角与脸颊。她怀中抱着一把奇特的乐琴，琴弦像是水波凝结，在她指尖下轻颤。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_14_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [163]={next_id=164, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="旋律正是从她手中的乐琴里流淌而出，轻柔、悠远，带着一丝淡淡的怅惘。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_14_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [164]={next_id=165, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她垂着眼帘，神情专注而宁静，仿佛周遭的一切喧嚣与危险都与她无关，唯有手中的琴弦响起旋律。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_14_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [165]={next_id=166, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你下意识放轻了脚步，甚至忘记了身后冰面下的威胁。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_14_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
