   [167]={next_id=168, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她似乎觉察到了你的目光，弹奏的动作微微一顿，缓缓抬头。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_14_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [168]={next_id=169, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="翡翠般的眼眸在阴沉的天光下闪烁着柔和的光芒，带着一丝不易察觉的好奇，望向你这个不速之客。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_14_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
